// [ERR] Avisos de error · Preparar aviso sin datos
// Compone el aviso (flujo, nodo, error, fecha, enlace) a partir del item del
// Error Trigger y enmascara lo que NO debe salir por correo. Modo "Run Once
// for All Items": el Error Trigger entrega 1 solo item y la búsqueda tolerante
// de campos es más simple (y más ligera) en una sola pasada.
//
// POLÍTICA DE ENMASCARADO (RGPD, spec §9, CA-2) — elegida: enmascarado COMPLETO.
//   · Emails → `***@***` · Teléfonos españoles de 9 cifras (con o sin espacios,
//     `6XX XXX XXX`, con o sin prefijo 34) → `***` · Nombres de cliente (solo cuando van detrás de
//     una preposición típica en español: «registrar a Carmen Ruiz», «cliente
//     …») → `***`. No se usa captura parcial tipo `c***@example.com`: el aviso
//     es diagnóstico (qué falló y dónde); el detalle completo con los datos
//     queda a un clic en el enlace a la ejecución de n8n.
//   · Secretos: `X-API-Key`, `Authorization`, `Bearer …`, `password`, `apiKey`,
//     `token`, `clave`, `contraseña`, `secret` conservan la etiqueta y pierden
//     el valor (`X-API-Key: ***`, `Bearer ***`); además, todo bloque alfanumérico
//     de 32+ caracteres y todo token con puntos tipo JWT (segmentos de 20+
//     caracteres) → `***`, con o sin etiqueta `Bearer` delante.
//   · El enmascarado se aplica SIEMPRE al mensaje completo ANTES de recortar a
//     600 caracteres: recortar primero podría cortar un token por la mitad y
//     dejar mitades de <32 caracteres en claro.
//   · El item del Error Trigger varía entre versiones de n8n: cada campo se
//     busca en la raíz, en `body`, en `execution` y en `execution.error`, con
//     valores por defecto si falta algo (ver nota pegajosa).
const item = $input.first().json ?? {};
const desdeBody = item && typeof item.body === 'object' ? item.body : {};
const ejecucion = item.execution ?? desdeBody.execution ?? {};
const errorEjec = ejecucion.error ?? desdeBody.error ?? {};
const flujoRaw = item.workflow ?? desdeBody.workflow ?? {};

// Secretos: la etiqueta queda, el valor se cambia por *** (F-005-2).
function enmascararSecretos(texto) {
  return texto
    .replace(/(x-api-key|authorization)\s*[:=]\s*\S+/gi, '$1: ***')
    .replace(/(password|api-?key|accesstoken|token|secret|clave|contrase\u00f1a)\s*[:=]\s*\S+/gi, '$1: ***')
    .replace(/Bearer\s+\S+/gi, 'Bearer ***')
    // Token con puntos tipo JWT: segmentos de 20+ en el primero → `***` (va
    // ANTES); la regla de bloque de 32+ queda después como segunda defensa.
    .replace(/[A-Za-z0-9_\-]{20,}(?:\.[A-Za-z0-9_\-]+)+/g, '***')
    .replace(/\b[A-Za-z0-9_\-]{32,}\b/g, '***');
}

// Datos personales. Orden: secretos → emails → teléfonos → nombres (F-005-4).
function enmascarar(texto) {
  let t = String(texto ?? '');
  t = enmascararSecretos(t);
  t = t.replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '***@***');
  t = t.replace(/\b(?:34[\s.\-])?[6789]\d{2}[\s.\-]\d{3}[\s.\-]\d{3}\b/g, '***');
  t = t.replace(/\b(?:34)?[6789]\d{8}\b/g, '***');
  // Nombre plausible: dos o tres palabras en mayúscula inicial tras una
  // preposición típica («a / al / del / la / para / cliente»). Limitación
  // conocida: si el error nombra a un cliente sin esa estructura, no se
  // detecta; por eso el aviso nunca deber ser la fuente de datos de clientes.
  t = t.replace(/\b([aA]l|[aA]|[dD]el?|[eE]l|[lL]a|[pP]ara|[cC]liente)\s+([A-Z\u00c1\u00c9\u00cd\u00d3\u00da\u00dc][a-z\u00e1\u00e9\u00ed\u00f3\u00fa\u00fc]+(?:\s+(?:[A-Z\u00c1\u00c9\u00cd\u00d3\u00da\u00dc][a-z\u00e1\u00e9\u00ed\u00f3\u00fa\u00fc]+|de|la|del)){1,2})\b/g, '$1 ***');
  return t;
}

// Búsqueda tolerante: los campos pueden venir en varias claves/posiciones.
function buscar(contenedores, claves) {
  for (const c of contenedores) {
    if (c && typeof c === 'object') {
      for (const k of claves) {
        const v = c[k];
        if (v != null && v !== '') {
          return v;
        }
      }
    }
  }
  return undefined;
}

try {
  let nombreFlujo = 'Flujo desconocido';
  let idFlujo = '';
  if (flujoRaw && typeof flujoRaw.name === 'string' && flujoRaw.name) {
    nombreFlujo = flujoRaw.name;
  }
  if (flujoRaw && flujoRaw.id != null && flujoRaw.id !== '') {
    idFlujo = String(flujoRaw.id);
  }

  let nodo = buscar([ejecucion, desdeBody, item], ['lastNodeExecuted', 'last_node_executed']) ?? 'Nodo desconocido';

  let mensajeRaw = buscar([errorEjec], ['message', 'description']);
  mensajeRaw = mensajeRaw ?? buscar([errorEjec, ejecucion, desdeBody, item], ['errorMessage', 'detail']) ?? '';
  let mensaje = typeof mensajeRaw === 'string' ? mensajeRaw : JSON.stringify(mensajeRaw);
  const LIMITE = 600;
  // Enmascarar el mensaje completo ANTES de recortarlo (ver política arriba).
  mensaje = mensaje ? enmascarar(mensaje) : 'Sin mensaje del error';
  mensaje = mensaje.length > LIMITE ? mensaje.slice(0, LIMITE) + '…' : mensaje;

  // Fecha y hora en zona Europe/Madrid, formato español.
  const inicio = buscar([ejecucion, desdeBody, item], ['startedAt', 'started_at']);
  let dt = inicio != null ? DateTime.fromISO(String(inicio)) : DateTime.now();
  if (!dt.isValid) {
    dt = DateTime.now();
  }
  const fecha = dt.setZone('Europe/Madrid').toFormat('dd/MM/yyyy HH:mm');

  const url = buscar([ejecucion, desdeBody, item], ['url']) ?? 'Enlace no incluido por esta versión de n8n';

  return [{
    json: {
      flujo: nombreFlujo + (idFlujo ? ` (id ${idFlujo})` : ''),
      nodo,
      fecha,
      error_txt: mensaje,
      detalle: String(url)
    }
  }];
} catch (e) {
  // El aviso es el último recurso: si prepararlo falla, envía lo mínimo.
  try {
    return [{
      json: {
        flujo: 'Flujo desconocido',
        nodo: 'Nodo desconocido',
        fecha: DateTime.now().setZone('Europe/Madrid').toFormat('dd/MM/yyyy HH:mm'),
        error_txt: enmascarar(`No se pudo leer el item del Error Trigger: ${String(e && e.message ? e.message : e)}`),
        detalle: 'Enlace no disponible'
      }
    }];
  } catch (e2) {
    return [{
      json: {
        flujo: 'Fallo en un flujo',
        nodo: 'Nodo desconocido',
        fecha: 'Fecha no disponible',
        error_txt: 'No se pudo preparar el aviso con detalle. Ver la ejecución en n8n.',
        detalle: 'Enlace no disponible'
      }
    }];
  }
}

